insert into public.story_pages (story_id, page_index, text, scene_description, image_asset_id, audio_asset_id, audio_duration_sec, word_timings) values ('tortoise-hare', 1, 'Once upon a time, in a green meadow, lived a hare who was very proud of how fast he could run. "Nobody can beat me!" he laughed. A quiet tortoise smiled and said, "I will race you." The hare giggled so hard his ears wobbled.', 'the hare laughing proudly at the tortoise on a sunny flower meadow, other animals watching', 'tortoise-hare-1-img', 'tortoise-hare-1-aud', 21.081, '[[0.107,0.384,"Once"],[0.505,0.355,"upon"],[0.874,0.071,"a"],[0.959,0.469,"time"],[1.755,0.128,"in"],[1.897,0.071,"a"],[1.982,0.398,"green"],[2.394,0.455,"meadow"],[3.203,0.27,"lived"],[3.487,0.057,"a"],[3.559,0.455,"hare"],[4.027,0.17,"who"],[4.212,0.213,"was"],[4.439,0.426,"very"],[4.88,0.44,"proud"],[5.334,0.128,"of"],[5.476,0.27,"how"],[5.76,0.511,"fast"],[6.286,0.156,"he"],[6.456,0.199,"could"],[6.669,0.426,"run"],[8.082,0.625,"Nobody"],[8.722,0.241,"can"],[8.977,0.27,"beat"],[9.261,0.284,"me"],[9.872,0.17,"he"],[10.057,0.625,"laughed"],[11.662,0.128,"A"],[11.804,0.597,"quiet"],[12.415,0.554,"tortoise"],[12.983,0.639,"smiled"],[13.636,0.199,"and"],[13.849,0.398,"said"],[14.56,0.199,"I"],[14.773,0.27,"will"],[15.057,0.384,"race"],[15.455,0.341,"you"],[16.776,0.17,"The"],[16.96,0.398,"hare"],[17.372,0.511,"giggled"],[17.898,0.327,"so"],[18.239,0.455,"hard"],[18.707,0.227,"his"],[18.949,0.384,"ears"],[19.347,0.696,"wobbled"]]'::jsonb) on conflict (story_id, page_index) do update set text = excluded.text, word_timings = excluded.word_timings, audio_duration_sec = excluded.audio_duration_sec;
