insert into public.story_pages (story_id, page_index, text, scene_description, image_asset_id, audio_asset_id, audio_duration_sec, word_timings) values ('luna-firefly', 1, 'Luna was the smallest firefly in the garden, and her light was the softest of all. One night she floated by a window, where a little girl lay awake. "I don''t like the dark," the girl whispered to her teddy bear.', 'the little firefly floating outside a bedroom window at night, the girl in bed hugging a teddy bear inside', 'luna-firefly-1-img', 'luna-firefly-1-aud', 18.26, '[[0.107,0.582,"Luna"],[0.703,0.241,"was"],[0.959,0.128,"the"],[1.101,0.71,"smallest"],[1.826,0.81,"firefly"],[2.649,0.128,"in"],[2.791,0.114,"the"],[2.919,0.568,"garden"],[3.843,0.156,"and"],[4.013,0.199,"her"],[4.226,0.412,"light"],[4.652,0.199,"was"],[4.865,0.114,"the"],[4.993,0.739,"softest"],[5.746,0.128,"of"],[5.888,0.384,"all"],[7.259,0.355,"One"],[7.628,0.327,"night"],[7.969,0.227,"she"],[8.21,0.611,"floated"],[8.835,0.199,"by"],[9.048,0.114,"a"],[9.176,0.554,"window"],[10.099,0.199,"where"],[10.312,0.085,"a"],[10.412,0.355,"little"],[10.781,0.398,"girl"],[11.193,0.241,"lay"],[11.449,0.597,"awake"],[13.026,0.17,"I"],[13.21,0.327,"don''t"],[13.551,0.298,"like"],[13.864,0.156,"the"],[14.034,0.497,"dark"],[14.858,0.156,"the"],[15.028,0.398,"girl"],[15.44,0.568,"whispered"],[16.023,0.142,"to"],[16.179,0.185,"her"],[16.378,0.384,"teddy"],[16.776,0.44,"bear"]]'::jsonb) on conflict (story_id, page_index) do update set text = excluded.text, word_timings = excluded.word_timings, audio_duration_sec = excluded.audio_duration_sec;
