insert into public.story_pages (story_id, page_index, text, scene_description, image_asset_id, audio_asset_id, audio_duration_sec, word_timings) values ('ugly-duckling', 1, 'On a farm by the pond, a mother duck''s eggs hatched one by one. The last duckling was big and grey and fluffy, not like the others at all. "What an odd little duck," the farm animals whispered, and the duckling felt very alone.', 'the grey duckling standing apart from small yellow ducklings by a farm pond, looking sad', 'ugly-duckling-1-img', 'ugly-duckling-1-aud', 19.905, '[[0.107,0.213,"On"],[0.334,0.071,"a"],[0.419,0.455,"farm"],[0.888,0.213,"by"],[1.115,0.142,"the"],[1.272,0.54,"pond"],[2.181,0.043,"a"],[2.237,0.455,"mother"],[2.706,0.398,"duck''s"],[3.118,0.355,"eggs"],[3.487,0.511,"hatched"],[4.013,0.327,"one"],[4.354,0.213,"by"],[4.581,0.469,"one"],[6.037,0.17,"The"],[6.222,0.497,"last"],[6.733,0.511,"duckling"],[7.259,0.227,"was"],[7.5,0.384,"big"],[7.898,0.17,"and"],[8.082,0.44,"grey"],[8.537,0.185,"and"],[8.736,0.611,"fluffy"],[9.645,0.284,"not"],[9.943,0.27,"like"],[10.227,0.128,"the"],[10.369,0.469,"others"],[10.852,0.156,"at"],[11.023,0.384,"all"],[12.386,0.284,"What"],[12.685,0.199,"an"],[12.898,0.341,"odd"],[13.253,0.355,"little"],[13.622,0.44,"duck"],[14.361,0.128,"the"],[14.503,0.412,"farm"],[14.929,0.611,"animals"],[15.554,0.639,"whispered"],[16.534,0.17,"and"],[16.719,0.142,"the"],[16.875,0.554,"duckling"],[17.443,0.355,"felt"],[17.812,0.44,"very"],[18.267,0.582,"alone"]]'::jsonb) on conflict (story_id, page_index) do update set text = excluded.text, word_timings = excluded.word_timings, audio_duration_sec = excluded.audio_duration_sec;
